// No row from Load Route means the lead does not exist, and the chain never
// reaches here - so no token can be minted for an unknown lead_id.
const r = $('Load Route').first().json;
const trg = $('When Executed by Another Workflow').first().json || {};

const hours = Number(trg.hours) > 0 ? Number(trg.hours) : 48;
const exp = new Date(Date.now() + hours * 3600 * 1000);

// The token's unguessability comes from the HMAC signature, not from jti;
// jti is here so two tokens minted in the same second are still distinct.
const jti = (globalThis.crypto && globalThis.crypto.randomUUID)
  ? globalThis.crypto.randomUUID()
  : Date.now().toString(36) + Math.random().toString(36).slice(2, 12);

// exp_iso is deliberately OUTSIDE the signed claims - it is only needed for
// the landing_tokens row and the caller, and signing it would just bloat
// every token with a duplicate of exp.
return [{ json: {
  claims: {
    lead_id: r.lead_id,
    route: r.route,
    jti,
    iat: Math.floor(Date.now() / 1000),
    exp: Math.floor(exp.getTime() / 1000)
  },
  exp_iso: exp.toISOString()
}}];

