const s = $('Sign JWT').first().json;
const token = s.token || s.jwt || s.signature;
const c = $('Build Claims').first().json;

return [{ json: {
  url: 'https://go.brandsure.in/a?t=' + token,
  token,
  lead_id: c.claims.lead_id,
  route: c.claims.route,
  expires_at: c.exp_iso
}}];
